def main():
    parser = argparse.ArgumentParser(description="Agente Centinela Autónomo Bilingüe de GitHub Discussions para el Portafolio")
    parser.add_argument("--owner", default=OWNER_DEFAULT, help="Propietario del repositorio")
    parser.add_argument("--repo", default=REPO_DEFAULT, help="Nombre del repositorio")
    parser.add_argument("--discussion-number", type=int, help="Número de discusión específico")
    parser.add_argument("--dry-run", action="store_true", help="Simular sin publicar comentarios ni crear issues")
    parser.add_argument("--force", action="store_true", help="Forzar respuesta omitiendo comprobación de duplicados")
    parser.add_argument("--no-wait", action="store_true", help="Omitir ventana de espera de 10 minutos")
    args = parser.parse_args()

    repo_env = os.environ.get("GITHUB_REPOSITORY")
    if repo_env and "/" in repo_env:
        parts = repo_env.split("/")
        args.owner = parts[0]
        args.repo = parts[1]

    log(f"Iniciando centinela para {args.owner}/{args.repo}...")
    context = gather_repository_context()

    if args.discussion_number:
        try:
            discussions = [get_discussion_details(args.owner, args.repo, args.discussion_number)]
        except Exception as e:
            log(f"Error al obtener detalles de #{args.discussion_number}: {e}")
            discussions = []
    else:
        discussions = get_open_discussions(args.owner, args.repo)

    log(f"Analizando {len(discussions)} discusión(es)...")
    records_atendidos = []

    for disc in discussions:
        disc_num = disc.get("number")
        title = disc.get("title", "")
        disc_id = disc.get("id")
        created_at_str = disc.get("createdAt")
        category = (disc.get("category") or {}).get("name", "General")
        url_disc = disc.get("url", f"https://github.com/{args.owner}/{args.repo}/discussions/{disc_num}")

        target_comment = needs_response(disc, force=args.force)
        if not target_comment:
            log(f"Discusión #{disc_num} ('{title}') está al día o ya respondida. Omitiendo.")
            continue

        author = target_comment.get("author", {}).get("login", "") or disc.get("author", {}).get("login", "")
        query_text = target_comment.get("body", "")

        # 1. Detección de Idioma
        lang = detect_language(title + " " + query_text)
        log(f"Procesando Discusión #{disc_num} ('{title}') | Autor: @{author} | Idioma detectado: {lang.upper()}...")

        # 2. Detección y Escalamiento de Seguridad / Bugs
        escalation_data = detect_security_or_bug_escalation(title, query_text)
        escalation_cat = escalation_data[0] if escalation_data else None

        # 3. Generación de Respuesta Técnica en Prosa Densa
        base_response = generate_response(disc, target_comment, context, lang=lang, escalation=escalation_cat)

        # 4. Inyección del Pie con Notificación Nivel 1 (Mención y Enlace de Validación)
        if lang == "en":
            footer = f"""

---
> {SIGNATURE_MARKER_EN} based on portfolio architecture.*  
> 🔔 **Notice for @{args.owner}:** Response ready for review. You may [verify and mark as answer here]({url_disc})."""
        else:
            footer = f"""

---
> {SIGNATURE_MARKER} en base a la arquitectura del portafolio.*  
> 🔔 **Aviso para @{args.owner}:** Respuesta lista para tu revisión. Puedes [validarla y marcarla como definitiva aquí]({url_disc})."""

        full_response = base_response + footer

        # 5. Cálculo de la Ventana de Espera Humana de 10 Minutos
        created_dt = parse_iso8601_utc(created_at_str)
        now_utc = datetime.now(timezone.utc)
        elapsed_seconds = max(0.0, (now_utc - created_dt).total_seconds())
        target_wait_seconds = MIN_WAIT_MINUTES * 60.0
        remaining_wait_minutes = max(0.0, (target_wait_seconds - elapsed_seconds) / 60.0)

        if args.dry_run:
            log(f"[DRY-RUN] Simulación de respuesta para #{disc_num}:")
            print(full_response)
            records_atendidos.append({
                "numero": disc_num,
                "titulo": title,
                "autor": author,
                "idioma": lang,
                "estado": "Simulado (DRY-RUN)",
                "escalado": escalation_cat,
                "url": url_disc,
                "fecha": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC"),
                "reply": full_response
            })
            continue

        # 6. Despacho Inmediato de Borrador a Discord DM y WhatsApp en Paralelo
        send_discord_draft_notification(
            discussion_num=disc_num,
            title=title,
            author=author,
            url=url_disc,
            category=category,
            draft_text=full_response,
            wait_minutes_remaining=remaining_wait_minutes,
            escalation=escalation_cat
        )
        send_whatsapp_draft_notification(
            discussion_num=disc_num,
            title=title,
            author=author,
            url=url_disc,
            category=category,
            draft_text=full_response,
            wait_minutes_remaining=remaining_wait_minutes,
            escalation=escalation_cat
        )

        # 7. Ventana de Espera Humana de 10 Minutos
        if elapsed_seconds < target_wait_seconds and not args.no_wait:
            wait_time = target_wait_seconds - elapsed_seconds
            log(f"Iniciando ventana de espera de 10 minutos ({wait_time:.1f} s restantes) para permitir revisión de @{args.owner}...")
            
            # Dormir en intervalos de hasta 60s con logs informativos
            time_left = wait_time
            while time_left > 0:
                step = min(60.0, time_left)
                time.sleep(step)
                time_left -= step
                if time_left > 0:
                    log(f"Ventana humana activa: {time_left/60.0:.1f} minutos restantes...")

            # 8. Verificación de Intervención Humana durante la Ventana
            log(f"Ventana de espera concluida. Verificando si @{args.owner} intervino manualmente...")
            try:
                disc_fresh = get_discussion_details(args.owner, args.repo, disc_num)
                fresh_comments = disc_fresh.get("comments", {}).get("nodes", [])
                maintainer_replied = any(
                    (c.get("author") or {}).get("login", "").lower() == args.owner.lower()
                    for c in fresh_comments
                )
                if maintainer_replied:
                    log(f"Intervención manual de @{args.owner} detectada en #{disc_num}. Cancelando publicación automática.")
                    send_discord_cancelled_notification(disc_num, title, author, url_disc)
                    send_whatsapp_cancelled_notification(disc_num, title, author, url_disc)
                    records_atendidos.append({
                        "numero": disc_num,
                        "titulo": title,
                        "autor": author,
                        "idioma": lang,
                        "estado": "Cancelado (Intervención manual de @Luics415)",
                        "escalado": escalation_cat,
                        "url": url_disc,
                        "fecha": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC"),
                        "reply": full_response
                    })
                    continue
            except Exception as e:
                log(f"Aviso al verificar intervención manual tras la espera: {e}")

        # 9. Publicación en GitHub Discussions
        url_comentario = post_reply(
            discussion_id=disc_id,
            body=full_response,
            reply_to_id=target_comment.get("id"),
            dry_run=args.dry_run
        )

        if url_comentario:
            log(f"Comentario publicado con éxito en #{disc_num}: {url_comentario}")

            # 10. Escalamiento en GitHub Issues si aplica
            if escalation_cat:
                escalate_issue_to_github(
                    owner=args.owner,
                    repo=args.repo,
                    disc_number=disc_num,
                    title=title,
                    author=author,
                    comment_url=url_comentario,
                    category=escalation_cat,
                    text=query_text,
                    dry_run=args.dry_run
                )

            # 11. Notificaciones de Publicación Exitosa (Discord, WhatsApp y Telegram)
            send_discord_published_notification(disc_num, title, author, url_comentario, category, escalation_cat)
            send_whatsapp_published_notification(disc_num, title, author, url_comentario)
            send_telegram_notification(args.owner, args.repo, disc_num, title, author, url_comentario)

            records_atendidos.append({
                "numero": disc_num,
                "titulo": title,
                "autor": author,
                "idioma": lang,
                "estado": "Publicado exitosamente",
                "escalado": escalation_cat,
                "url": url_comentario,
                "fecha": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC"),
                "reply": full_response
            })

    # 12. Notificación Nivel 2 (GitHub Actions Step Summary)
    write_step_summary(records_atendidos)

    # 13. Historial en Expediente (docs/FechaAgente/)
    record_in_expediente(records_atendidos, dry_run=args.dry_run)

    log(f"Ejecución completada. Total de discusiones procesadas: {len(records_atendidos)}.")


if __name__ == "__main__":
    main()
